def calculate_L(m, n):
    # x_n = n, x_m = m
    # L_m,n = (m+n) * |n^2 - m^2|
    # Since n > m, n^2 - m^2 = (n-m)(n+m) > 0
    return (m + n) * (n**2 - m**2)

min_L = float('inf')
all_Ls = []

# Check for 1 <= m < n <= 10
for n in range(2, 11):
    for m in range(1, n):
        L_mn = calculate_L(m, n)
        all_Ls.append((m, n, L_mn))
        if L_mn < min_L:
            min_L = L_mn

print(f"Minimum observed value (candidate D): {min_L}")
print("All calculated values (m, n, L_mn):")
for m, n, L_mn in all_Ls:
    print(f"({m}, {n}): {L_mn}")

